import { useState } from 'react'
import { IconButton } from '@freshworks/dew-components'
import { InfoIcon } from '../dew/shared/IllustrationIcons'
import styles from './ActionBanner.module.css'

/**
 * The banner's output footer, lifted out so any AI card can end the same way:
 * "Generated by Freshworks AI" on the left, "Helpful? Yes / No" on the right,
 * below the content rather than in the header.
 */
export function AiFeedbackFooter({ onFeedback }: { onFeedback?: (helpful: boolean) => void }) {
  const [choice, setChoice] = useState<'yes' | 'no' | null>(null)
  const choose = (helpful: boolean) => {
    setChoice(helpful ? 'yes' : 'no')
    onFeedback?.(helpful)
  }
  return (
    <div className={styles.footer}>
      <div className={styles.disclaimer}>
        <span>Generated by Freshworks AI</span>
        <InfoIcon className={styles.infoIcon} />
      </div>
      <div className={styles.feedback} aria-live="polite">
        {choice === null ? (
          <div className={styles.feedbackAsk} role="group" aria-label="Was this helpful?">
            <IconButton iconName="Actions/Upvote" aria-label="Helpful" size="mini" onClick={() => choose(true)} />
            <IconButton iconName="Actions/Downvote" aria-label="Not helpful" size="mini" onClick={() => choose(false)} />
          </div>
        ) : (
          <p className={styles.feedbackThanks}>Thanks for your feedback!</p>
        )}
      </div>
    </div>
  )
}
